'use strict';
const robots=window.ROBOTS||[];
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=u=>/^https?:\/\//i.test(u||'')?u:null;
let view=location.pathname.endsWith('wiki.html')?'wiki':'cards', selected=new Set(), toastTimer;
const filters=[['country','country'],['fingers','fingers'],['category','category'],['price-kind','priceKind']];
for(const [id,key] of filters){for(const v of [...new Set(robots.map(r=>r[key]))].sort((a,b)=>a.localeCompare(b,'ko'))){const o=document.createElement('option');o.value=v;o.textContent=v;$(id).append(o)}$(id).addEventListener('change',render)}
$('stats').innerHTML=`<div><b>${robots.length}</b><small>ROBOT HANDS</small></div><div><b>${new Set(robots.map(r=>r.country)).size}</b><small>COUNTRIES</small></div><div><b>${new Set(robots.map(r=>r.maker)).size}</b><small>MAKER RECORDS</small></div>`;
const hero=robots.find(r=>r.name==='Allegro Hand V5 Plus');if(hero?.image)$('hero-image').src=hero.image;
function filtered(){const q=$('search').value.trim().toLocaleLowerCase();return robots.filter(r=>(!q||[r.name,r.maker,r.specs,r.country,r.category].join(' ').toLocaleLowerCase().includes(q))&&filters.every(([id,k])=>!$(id).value||r[k]===$(id).value)).sort((a,b)=>a[$('sort').value].localeCompare(b[$('sort').value],'ko'))}
function photo(r){return r.image?`<img src="${esc(r.image)}" alt="${esc(r.name)} 제품 사진" loading="lazy">`:'<span class="image-missing">제품 이미지 미수집<br>원문에서 확인</span>'}
function check(r){return `<label><input type="checkbox" data-select="${r.id}" ${selected.has(r.id)?'checked':''} aria-label="${esc(r.name)} 비교 선택"> 비교 담기</label>`}
function render(){document.body.classList.toggle('wiki',view==='wiki');$('cards-view').setAttribute('aria-pressed',view==='cards');$('wiki-view').setAttribute('aria-pressed',view==='wiki');const list=filtered();$('count').innerHTML=`<strong>${list.length}</strong>개 모델 <span> / 전체 ${robots.length}개 · 노션 수집 2026.11.12</span>`;$('empty').hidden=!!list.length;
 if(view==='cards'){$('results').className='grid';$('results').innerHTML=list.map((r,i)=>`<article class="card"><div class="card-image"><span class="card-index">H / ${String(i+1).padStart(3,'0')}</span>${photo(r)}</div><div class="card-content"><div class="country-tag">${esc(r.country)} · ${esc(r.category)}</div><h3><button data-detail="${r.id}">${esc(r.name)}</button></h3><div class="maker">${esc(r.maker)}</div><p class="spec-snippet">${esc(r.specs)}</p><div class="chips"><span class="chip">${esc(r.fingers)} 핑거</span><span class="chip price">${esc(r.priceKind)}</span></div><div class="card-bottom">${check(r)}<button data-detail="${r.id}" aria-label="${esc(r.name)} 상세 보기">상세 보기 ↗</button></div></div></article>`).join('')}
 else{$('results').className='table-wrap';$('results').innerHTML=`<table><caption class="sr-only">로봇핸드 사양 목록</caption><thead><tr><th>비교</th><th>모델 / 제조사</th><th>국가</th><th>핑거</th><th>사양 원문</th><th>가격 / 근거</th></tr></thead><tbody>${list.map(r=>`<tr><td>${check(r)}</td><td><button data-detail="${r.id}">${esc(r.name)}</button><small>${esc(r.maker)}</small></td><td>${esc(r.country)}</td><td>${esc(r.fingers)}</td><td class="spec-cell">${esc(r.specs)}</td><td>${esc(r.price)}<small>${esc(r.priceKind)}</small></td></tr>`).join('')}</tbody></table>`}
 for(const img of $('results').querySelectorAll('img'))img.addEventListener('error',()=>{img.outerHTML='<span class="image-missing">이미지를 불러올 수 없습니다.</span>'},{once:true});updateTray();}
function link(url,title){return safeUrl(url)?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a>`:''}
function detail(id){const r=robots.find(r=>r.id===id);if(!r)return;$('detail-body').innerHTML=`<div class="detail-grid"><div class="detail-photo">${photo(r)}</div><div><div class="eyebrow">${esc(r.country)} / ${esc(r.category)}</div><h2>${esc(r.name)}</h2><p>${esc(r.maker)}<br>${esc(r.location)}</p><div class="chips"><span class="chip">${esc(r.fingers)} 핑거</span><span class="chip price">${esc(r.priceKind)}</span></div><h3>사양 / 노션 원문</h3><p>${esc(r.specs)}</p><h3>가격과 조건</h3><p>${esc(r.price)}</p><div class="detail-links">${link(r.url,'제조사·제품 자료')}${link(r.priceUrl,'가격 근거')}${link(r.notion,'노션 원본')}</div></div></div><div class="detail-notes"><strong>검토 메모 · 구성 및 가격 주의</strong><br>${esc(r.notes)}<p>데이터 수집일 ${r.collected} · 제조사 최신 사양 및 견적을 다시 확인하세요.</p></div><h3>관련 연구 ${r.papers.length?`(${r.papers.length})`:''}</h3><div class="detail-links">${r.papers.length?r.papers.map((u,i)=>link(u,`연구 자료 ${i+1}`)).join(''):'등록된 연구 링크 없음'}</div>`;$('detail').showModal();history.replaceState(null,'','#model='+id)}
function updateTray(){const list=robots.filter(r=>selected.has(r.id));$('compare-tray').hidden=!list.length;$('selected-count').textContent=`${list.length} / 3 모델 선택`;$('selected-names').textContent=list.map(r=>r.name).join(' · ');$('compare-open').disabled=list.length<2;}
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',3000)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-detail]');if(b)detail(b.dataset.detail)});
document.addEventListener('change',e=>{if(!e.target.matches('[data-select]'))return;const id=e.target.dataset.select;if(e.target.checked){if(selected.size>=3){e.target.checked=false;toast('최대 3개 모델까지 비교할 수 있습니다.');return}selected.add(id)}else selected.delete(id);updateTray()});
function reset(){$('search').value='';filters.forEach(([id])=>$(id).value='');render()}
$('search').addEventListener('input',render);$('sort').addEventListener('change',render);$('reset').onclick=reset;$('empty-reset').onclick=reset;
$('cards-view').onclick=()=>{view='cards';render()};$('wiki-view').onclick=()=>{view='wiki';render()};$('compare-clear').onclick=()=>{selected.clear();render()};
$('compare-open').onclick=()=>{const list=robots.filter(r=>selected.has(r.id));if(list.length<2)return;const keys=[['maker','제조사'],['country','국가'],['fingers','손가락 수'],['specs','사양 원문'],['priceKind','가격 근거'],['price','가격 원문'],['notes','검토 메모']];$('compare-body').innerHTML=`<div class="table-wrap"><table class="compare-table"><thead><tr><th>비교 항목</th>${list.map(r=>`<th>${photo(r)}<h3>${esc(r.name)}</h3></th>`).join('')}</tr></thead><tbody>${keys.map(([k,t])=>`<tr class="${new Set(list.map(r=>r[k])).size>1?'different':''}"><th>${t} ${new Set(list.map(r=>r[k])).size>1?'≠':''}</th>${list.map(r=>`<td>${esc(r[k])}</td>`).join('')}</tr>`).join('')}<tr><th>출처</th>${list.map(r=>`<td>${link(r.url,'제품 자료')}<br>${link(r.notion,'노션')}</td>`).join('')}</tr></tbody></table></div><p>상이한 세대·가격 조건·측정 조건을 동일 성능이나 확정 판매가로 해석하지 마세요.</p>`;$('comparison').showModal()};
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close()}})});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('search').focus()}});
render();if(location.hash.startsWith('#model='))detail(location.hash.slice(7));
